/* === js/indicators/overlays/DoubleEMA.js === */
/**
 * DoubleEMA.js
 * Double Exponential Moving Average (DEMA).
 *   DEMA = 2 * EMA(src) - EMA(EMA(src))
 * Reduces lag versus a single EMA of the same period.
 *
 * Note: we use a NaN-tolerant EMA helper because the first EMA's output has
 * NaN values for the first `period-1` bars, which would otherwise break the
 * seeding of the second EMA.
 */
class DoubleEMA extends IndicatorBase {
    constructor(opts = {}) {
        super(opts);
        this.name = 'DoubleEMA';
        this.type = 'overlay';
        this.color = opts.color || '#12C4F0';
    }
    defaultOptions() { return { period: 21 }; }

    /** EMA that tolerates leading NaN values in `src` (seeds after `period` finite values). */
    _emaRobust(src, period) {
        const n = src.length;
        const out = new Float64Array(n);
        const k = 2 / (period + 1);
        let prev = NaN;
        let count = 0;
        let seedSum = 0;
        for (let i = 0; i < n; i++) {
            const v = src[i];
            if (!isFinite(v)) { out[i] = NaN; continue; }
            count++;
            if (count < period) {
                seedSum += v;
                out[i] = NaN;
            } else if (count === period) {
                seedSum += v;
                prev = seedSum / period;
                out[i] = prev;
            } else {
                prev = v * k + prev * (1 - k);
                out[i] = prev;
            }
        }
        return out;
    }

    calculate(dm) {
        const { closes } = dm.raw();
        const p = this.options.period;
        const ema1 = this._ema(closes, p);
        const ema2 = this._emaRobust(ema1, p);
        const out = new Float64Array(closes.length);
        for (let i = 0; i < closes.length; i++) {
            out[i] = isFinite(ema2[i]) ? 2 * ema1[i] - ema2[i] : NaN;
        }
        this.buffers.dema = out;
    }
    draw(ctx, viewport, dm, pane, theme) {
        this.ensureCalculated(dm);
        this._drawLine(ctx, viewport, this.buffers.dema, this.color, this.lineWidth, pane);
    }
}


/* === js/indicators/overlays/TripleEMA.js === */
/**
 * TripleEMA.js
 * Triple Exponential Moving Average (TEMA).
 *   TEMA = 3*EMA - 3*EMA(EMA) + EMA(EMA(EMA))
 */
class TripleEMA extends IndicatorBase {
    constructor(opts = {}) {
        super(opts);
        this.name = 'TripleEMA';
        this.type = 'overlay';
        this.color = opts.color || '#12C4F0';
    }
    defaultOptions() { return { period: 21 }; }

    _emaRobust(src, period) {
        const n = src.length;
        const out = new Float64Array(n);
        const k = 2 / (period + 1);
        let prev = NaN;
        let count = 0;
        let seedSum = 0;
        for (let i = 0; i < n; i++) {
            const v = src[i];
            if (!isFinite(v)) { out[i] = NaN; continue; }
            count++;
            if (count < period) {
                seedSum += v;
                out[i] = NaN;
            } else if (count === period) {
                seedSum += v;
                prev = seedSum / period;
                out[i] = prev;
            } else {
                prev = v * k + prev * (1 - k);
                out[i] = prev;
            }
        }
        return out;
    }

    calculate(dm) {
        const { closes } = dm.raw();
        const p = this.options.period;
        const e1 = this._ema(closes, p);
        const e2 = this._emaRobust(e1, p);
        const e3 = this._emaRobust(e2, p);
        const out = new Float64Array(closes.length);
        for (let i = 0; i < closes.length; i++) {
            out[i] = isFinite(e3[i]) ? 3 * e1[i] - 3 * e2[i] + e3[i] : NaN;
        }
        this.buffers.tema = out;
    }
    draw(ctx, viewport, dm, pane, theme) {
        this.ensureCalculated(dm);
        this._drawLine(ctx, viewport, this.buffers.tema, this.color, this.lineWidth, pane);
    }
}


/* === js/indicators/overlays/SMMA.js === */
/**
 * SMMA.js
 * Smoothed Moving Average, also known as RMA / Wilder's MA.
 *   SMMA[i] = (SMMA[i-1] * (period - 1) + src[i]) / period
 * Seed with a simple average of the first `period` values.
 *
 * Equivalent to _rma but exposed as a separate overlay indicator.
 */
class SMMA extends IndicatorBase {
    constructor(opts = {}) {
        super(opts);
        this.name = 'SMMA';
        this.type = 'overlay';
        this.color = opts.color || '#12C4F0';
    }
    defaultOptions() { return { period: 14 }; }
    calculate(dm) {
        const { closes } = dm.raw();
        this.buffers.smma = this._rma(closes, this.options.period);
    }
    draw(ctx, viewport, dm, pane, theme) {
        this.ensureCalculated(dm);
        this._drawLine(ctx, viewport, this.buffers.smma, this.color, this.lineWidth, pane);
    }
}


/* === js/indicators/overlays/VWMA.js === */
/**
 * VWMA.js
 * Volume Weighted Moving Average.
 *   VWMA[i] = sum(close[j] * volume[j]) / sum(volume[j]) over the last `period` bars.
 */
class VWMA extends IndicatorBase {
    constructor(opts = {}) {
        super(opts);
        this.name = 'VWMA';
        this.type = 'overlay';
        this.color = opts.color || '#12C4F0';
    }
    defaultOptions() { return { period: 20 }; }
    calculate(dm) {
        const { closes, volumes } = dm.raw();
        const n = closes.length;
        const p = this.options.period;
        const out = new Float64Array(n);
        let pvSum = 0;
        let vSum = 0;
        for (let i = 0; i < n; i++) {
            pvSum += closes[i] * volumes[i];
            vSum += volumes[i];
            if (i >= p) {
                pvSum -= closes[i - p] * volumes[i - p];
                vSum -= volumes[i - p];
            }
            if (i >= p - 1 && vSum !== 0) out[i] = pvSum / vSum;
            else out[i] = NaN;
        }
        this.buffers.vwma = out;
    }
    draw(ctx, viewport, dm, pane, theme) {
        this.ensureCalculated(dm);
        this._drawLine(ctx, viewport, this.buffers.vwma, this.color, this.lineWidth, pane);
    }
}


/* === js/indicators/overlays/HullMA.js === */
/**
 * HullMA.js
 * Hull Moving Average (Alan Hull).
 *   WMA2 = WMA(src, n/2)
 *   WMA  = WMA(src, n)
 *   diff = WMA2 * 2 - WMA
 *   HullMA = WMA(diff, sqrt(n))
 *
 * The result is a smoothed, low-lag moving average.
 */
class HullMA extends IndicatorBase {
    constructor(opts = {}) {
        super(opts);
        this.name = 'HullMA';
        this.type = 'overlay';
        this.color = opts.color || '#12C4F0';
    }
    defaultOptions() { return { period: 20 }; }
    calculate(dm) {
        const { closes } = dm.raw();
        const n = this.options.period;
        const half = Math.max(1, Math.floor(n / 2));
        const sqrtN = Math.max(1, Math.round(Math.sqrt(n)));

        const wmaHalf = this._wma(closes, half);
        const wmaFull = this._wma(closes, n);
        const diff = new Float64Array(closes.length);
        for (let i = 0; i < closes.length; i++) {
            diff[i] = isFinite(wmaHalf[i]) && isFinite(wmaFull[i]) ? 2 * wmaHalf[i] - wmaFull[i] : NaN;
        }
        // _wma requires finite values for the period window; use a NaN-tolerant WMA.
        this.buffers.hull = this._wmaRobust(diff, sqrtN);
    }
    /** WMA that tolerates leading NaN values in `src`. */
    _wmaRobust(src, period) {
        const n = src.length;
        const out = new Float64Array(n);
        const denom = period * (period + 1) / 2;
        // Maintain a sliding window of the last `period` finite values.
        const ring = new Array(period).fill(NaN);
        let count = 0;
        let ringIdx = 0;
        for (let i = 0; i < n; i++) {
            const v = src[i];
            if (isFinite(v)) {
                ring[ringIdx % period] = v;
                ringIdx++;
                count++;
            } else {
                out[i] = NaN;
                continue;
            }
            if (count < period) { out[i] = NaN; continue; }
            // Walk the ring from oldest (j=0, weight=1) to newest (j=period-1, weight=period).
            let sum = 0;
            const start = ringIdx % period;
            for (let j = 0; j < period; j++) {
                const val = ring[(start + j) % period];
                const weight = j + 1;
                sum += val * weight;
            }
            out[i] = sum / denom;
        }
        return out;
    }
    draw(ctx, viewport, dm, pane, theme) {
        this.ensureCalculated(dm);
        this._drawLine(ctx, viewport, this.buffers.hull, this.color, this.lineWidth, pane);
    }
}


/* === js/indicators/overlays/KAMA.js === */
/**
 * KAMA.js
 * Kaufman Adaptive Moving Average.
 *
 *   change = |close[i] - close[i - period]|
 *   volatility = sum_{j=i-period+1..i} |close[j] - close[j-1]|
 *   er = change / volatility  (efficiency ratio, in [0, 1]; 0 if vol == 0)
 *   fast = 2/(fastPeriod + 1)
 *   slow = 2/(slowPeriod + 1)
 *   sc  = (er * (fast - slow) + slow) ** 2    (smoothing constant)
 *   KAMA[i] = KAMA[i-1] + sc * (close[i] - KAMA[i-1])
 *
 * Seeds KAMA at the first bar where the period window is available with the
 * close price at that bar.
 */
class KAMA extends IndicatorBase {
    constructor(opts = {}) {
        super(opts);
        this.name = 'KAMA';
        this.type = 'overlay';
        this.color = opts.color || '#12C4F0';
    }
    defaultOptions() { return { period: 10, fastPeriod: 2, slowPeriod: 30 }; }
    calculate(dm) {
        const { closes } = dm.raw();
        const n = closes.length;
        const p = this.options.period;
        const fast = 2 / (this.options.fastPeriod + 1);
        const slow = 2 / (this.options.slowPeriod + 1);
        const out = new Float64Array(n);
        let prev = NaN;
        for (let i = 0; i < n; i++) {
            if (i < p) { out[i] = NaN; continue; }
            const change = Math.abs(closes[i] - closes[i - p]);
            let vol = 0;
            for (let j = i - p + 1; j <= i; j++) vol += Math.abs(closes[j] - closes[j - 1]);
            const er = vol === 0 ? 0 : change / vol;
            const sc = (er * (fast - slow) + slow) ** 2;
            if (!isFinite(prev)) {
                // Seed with current close once the first valid window is available.
                prev = closes[i];
                out[i] = prev;
                continue;
            }
            prev = prev + sc * (closes[i] - prev);
            out[i] = prev;
        }
        this.buffers.kama = out;
    }
    draw(ctx, viewport, dm, pane, theme) {
        this.ensureCalculated(dm);
        this._drawLine(ctx, viewport, this.buffers.kama, this.color, this.lineWidth, pane);
    }
}


/* === js/indicators/overlays/ALMA.js === */
/**
 * ALMA.js
 * Arnaud Legoux Moving Average.
 *
 * Gaussian-weighted moving average. For each window of size `period`, weights
 * are computed from a Gaussian function centered at `offset = (period - 1) *
 * (sigma / (period - 1))` with standard deviation `sigma`.
 *
 *   m = offset
 *   s = sigma
 *   norm = sum_{i=0..period-1} exp(-((i - m)^2) / (2*s*s))
 *   ALMA = sum_{i=0..period-1} src[i] * exp(-((i - m)^2) / (2*s*s)) / norm
 *
 * Convention: the most recent bar in the window corresponds to i = period - 1
 * (the rightmost/Gaussian peak).
 */
class ALMA extends IndicatorBase {
    constructor(opts = {}) {
        super(opts);
        this.name = 'ALMA';
        this.type = 'overlay';
        this.color = opts.color || '#12C4F0';
    }
    defaultOptions() { return { period: 9, sigma: 6, offset: 0.85 }; }
    calculate(dm) {
        const { closes } = dm.raw();
        const n = closes.length;
        const p = this.options.period;
        const sigma = this.options.sigma;
        const m = Math.floor((p - 1) * this.options.offset);
        const s = sigma;
        const w = new Float64Array(p);
        let norm = 0;
        for (let i = 0; i < p; i++) {
            const ww = Math.exp(-((i - m) ** 2) / (2 * s * s));
            w[i] = ww;
            norm += ww;
        }
        const out = new Float64Array(n);
        for (let i = p - 1; i < n; i++) {
            let acc = 0;
            // i - (p - 1) + j  ==  i - p + 1 + j  -> src index for window slot j
            for (let j = 0; j < p; j++) {
                acc += closes[i - p + 1 + j] * w[j];
            }
            out[i] = acc / norm;
        }
        this.buffers.alma = out;
    }
    draw(ctx, viewport, dm, pane, theme) {
        this.ensureCalculated(dm);
        this._drawLine(ctx, viewport, this.buffers.alma, this.color, this.lineWidth, pane);
    }
}


/* === js/indicators/overlays/VWAP.js === */
/**
 * VWAP.js
 * Volume Weighted Average Price.
 *
 * Cumulative from the start of each trading day. For each bar we add the
 * typical price * volume to a running sum and divide by the cumulative
 * volume. The accumulator resets whenever the calendar day (UTC) changes.
 *
 *   typical = (high + low + close) / 3
 *   vwap[i] = (pvSum_today + typical[i] * volume[i]) / (vSum_today + volume[i])
 */
class VWAP extends IndicatorBase {
    constructor(opts = {}) {
        super(opts);
        this.name = 'VWAP';
        this.type = 'overlay';
        this.color = opts.color || '#EA3943';
    }
    defaultOptions() { return {}; }

    static _dayOf(ts) {
        // UTC midnight timestamp (ms) for the day containing `ts`.
        const DAY = 86_400_000;
        return Math.floor(ts / DAY) * DAY;
    }

    calculate(dm) {
        const { highs, lows, closes, volumes, times } = dm.raw();
        const n = closes.length;
        const out = new Float64Array(n);
        let pvSum = 0;
        let vSum = 0;
        let curDay = null;
        for (let i = 0; i < n; i++) {
            const day = VWAP._dayOf(times[i]);
            if (curDay === null || day !== curDay) {
                curDay = day;
                pvSum = 0;
                vSum = 0;
            }
            const typical = (highs[i] + lows[i] + closes[i]) / 3;
            pvSum += typical * volumes[i];
            vSum += volumes[i];
            out[i] = vSum > 0 ? pvSum / vSum : closes[i];
        }
        this.buffers.vwap = out;
    }
    draw(ctx, viewport, dm, pane, theme) {
        this.ensureCalculated(dm);
        // Draw segment-by-segment so daily resets produce clean breaks.
        const buf = this.buffers.vwap;
        if (!buf) return;
        const leftIdx = Math.max(0, Math.floor(viewport.leftEdge));
        const rightIdx = Math.min(buf.length - 1, Math.ceil(viewport.rightEdge));
        const { times } = dm.raw();
        ctx.strokeStyle = this.color;
        ctx.lineWidth = this.lineWidth;
        ctx.setLineDash([]);
        ctx.beginPath();
        let started = false;
        let curDay = null;
        for (let i = leftIdx; i <= rightIdx; i++) {
            const v = buf[i];
            if (!isFinite(v)) { started = false; continue; }
            const day = VWAP._dayOf(times[i]);
            if (curDay !== null && day !== curDay) started = false;
            curDay = day;
            const x = viewport.indexToX(i) + viewport.barSpacing / 2;
            const y = this._priceToY(v, viewport, pane);
            if (!started) { ctx.moveTo(x, y); started = true; }
            else ctx.lineTo(x, y);
        }
        ctx.stroke();
    }
}


/* === js/indicators/overlays/AnchoredVWAP.js === */
/**
 * AnchoredVWAP.js
 * Volume Weighted Average Price from a user-defined anchor bar forward.
 *
 *   typical = (high + low + close) / 3
 *   vwap[i] = sum_{j=anchor..i}(typical[j] * volume[j]) / sum_{j=anchor..i}(volume[j])
 *
 * Bars before the anchor are NaN.
 */
class AnchoredVWAP extends IndicatorBase {
    constructor(opts = {}) {
        super(opts);
        this.name = 'AnchoredVWAP';
        this.type = 'overlay';
        this.color = opts.color || '#b39ddb';
    }
    defaultOptions() { return { anchorIndex: 0 }; }
    calculate(dm) {
        const { highs, lows, closes, volumes } = dm.raw();
        const n = closes.length;
        const out = new Float64Array(n);
        const anchor = Math.max(0, Math.min(n - 1, Math.floor(this.options.anchorIndex)));
        let pvSum = 0;
        let vSum = 0;
        for (let i = 0; i < n; i++) {
            if (i < anchor) { out[i] = NaN; continue; }
            const typical = (highs[i] + lows[i] + closes[i]) / 3;
            pvSum += typical * volumes[i];
            vSum += volumes[i];
            out[i] = vSum > 0 ? pvSum / vSum : closes[i];
        }
        this.buffers.vwap = out;
    }
    draw(ctx, viewport, dm, pane, theme) {
        this.ensureCalculated(dm);
        this._drawLine(ctx, viewport, this.buffers.vwap, this.color, this.lineWidth, pane);
    }
}


/* === js/indicators/overlays/BollingerBands.js === */
/**
 * BollingerBands.js
 * Bollinger Bands overlay.
 *   middle = SMA(close, period)
 *   upper  = middle + mult * stdev(close, period)
 *   lower  = middle - mult * stdev(close, period)
 * Renders 3 lines plus a translucent fill between upper and lower.
 */
class BollingerBands extends IndicatorBase {
    constructor(opts = {}) {
        super(opts);
        this.name = 'BollingerBands';
        this.type = 'overlay';
        this.color  = opts.color  || '#12C4F0'; // middle
        this.color2 = opts.color2 || '#EA3943'; // upper / lower lines
    }
    defaultOptions() { return { period: 20, mult: 2 }; }
    calculate(dm) {
        const { closes } = dm.raw();
        const p = this.options.period;
        const m = this.options.mult;
        const middle = this._sma(closes, p);
        const sd = this._stdev(closes, p);
        const n = closes.length;
        const upper = new Float64Array(n);
        const lower = new Float64Array(n);
        for (let i = 0; i < n; i++) {
            if (isFinite(middle[i]) && isFinite(sd[i])) {
                upper[i] = middle[i] + m * sd[i];
                lower[i] = middle[i] - m * sd[i];
            } else {
                upper[i] = NaN;
                lower[i] = NaN;
            }
        }
        this.buffers.middle = middle;
        this.buffers.upper = upper;
        this.buffers.lower = lower;
    }
    _drawBand(ctx, viewport, upper, lower, fill) {
        const leftIdx = Math.max(0, Math.floor(viewport.leftEdge));
        const rightIdx = Math.min(upper.length - 1, Math.ceil(viewport.rightEdge));
        ctx.beginPath();
        let started = false;
        // top edge L->R
        for (let i = leftIdx; i <= rightIdx; i++) {
            const v = upper[i];
            if (!isFinite(v)) { started = false; continue; }
            const x = viewport.indexToX(i) + viewport.barSpacing / 2;
            const y = this._priceToY(v, viewport, null);
            if (!started) { ctx.moveTo(x, y); started = true; }
            else ctx.lineTo(x, y);
        }
        // bottom edge R->L
        started = false;
        for (let i = rightIdx; i >= leftIdx; i--) {
            const v = lower[i];
            if (!isFinite(v)) { continue; }
            const x = viewport.indexToX(i) + viewport.barSpacing / 2;
            const y = this._priceToY(v, viewport, null);
            if (!started) { ctx.moveTo(x, y); started = true; }
            else ctx.lineTo(x, y);
        }
        ctx.closePath();
        ctx.fillStyle = fill;
        ctx.fill();
    }
    draw(ctx, viewport, dm, pane, theme) {
        this.ensureCalculated(dm);
        // Fill between upper and lower (low alpha).
        ctx.save();
        this._clipToPane(ctx, viewport, pane);
        this._drawBand(ctx, viewport, this.buffers.upper, this.buffers.lower,
            this._withAlpha(this.color2, 0.05));
        ctx.restore();
        // Lines.
        this._drawLine(ctx, viewport, this.buffers.upper,  this.color2, this.lineWidth, pane);
        this._drawLine(ctx, viewport, this.buffers.middle, this.color,  this.lineWidth, pane);
        this._drawLine(ctx, viewport, this.buffers.lower,  this.color2, this.lineWidth, pane);
    }
}


/* === js/indicators/overlays/KeltnerChannel.js === */
/**
 * KeltnerChannel.js
 * Keltner Channel overlay.
 *   middle = EMA(close, period)
 *   atr    = RMA(TR, atrPeriod)   where TR = max(high-low, |high-prevClose|, |low-prevClose|)
 *   upper  = middle + mult * atr
 *   lower  = middle - mult * atr
 * Renders 3 lines plus a translucent fill between upper and lower.
 */
class KeltnerChannel extends IndicatorBase {
    constructor(opts = {}) {
        super(opts);
        this.name = 'KeltnerChannel';
        this.type = 'overlay';
        this.color  = opts.color  || '#12C4F0';
        this.color2 = opts.color2 || '#EA3943';
    }
    defaultOptions() { return { period: 20, atrPeriod: 10, mult: 2 }; }

    _trueRange(highs, lows, closes) {
        const n = highs.length;
        const tr = new Float64Array(n);
        tr[0] = highs[0] - lows[0];
        for (let i = 1; i < n; i++) {
            const a = highs[i] - lows[i];
            const b = Math.abs(highs[i] - closes[i - 1]);
            const c = Math.abs(lows[i] - closes[i - 1]);
            tr[i] = Math.max(a, b, c);
        }
        return tr;
    }

    calculate(dm) {
        const { highs, lows, closes } = dm.raw();
        const n = closes.length;
        const p = this.options.period;
        const ap = this.options.atrPeriod;
        const m = this.options.mult;
        const middle = this._ema(closes, p);
        const tr = this._trueRange(highs, lows, closes);
        const atr = this._rma(tr, ap);
        const upper = new Float64Array(n);
        const lower = new Float64Array(n);
        for (let i = 0; i < n; i++) {
            if (isFinite(middle[i]) && isFinite(atr[i])) {
                upper[i] = middle[i] + m * atr[i];
                lower[i] = middle[i] - m * atr[i];
            } else {
                upper[i] = NaN;
                lower[i] = NaN;
            }
        }
        this.buffers.middle = middle;
        this.buffers.atr = atr;
        this.buffers.upper = upper;
        this.buffers.lower = lower;
    }

    _drawBand(ctx, viewport, upper, lower, fill) {
        const leftIdx = Math.max(0, Math.floor(viewport.leftEdge));
        const rightIdx = Math.min(upper.length - 1, Math.ceil(viewport.rightEdge));
        ctx.beginPath();
        let started = false;
        for (let i = leftIdx; i <= rightIdx; i++) {
            const v = upper[i];
            if (!isFinite(v)) { started = false; continue; }
            const x = viewport.indexToX(i) + viewport.barSpacing / 2;
            const y = this._priceToY(v, viewport, null);
            if (!started) { ctx.moveTo(x, y); started = true; }
            else ctx.lineTo(x, y);
        }
        started = false;
        for (let i = rightIdx; i >= leftIdx; i--) {
            const v = lower[i];
            if (!isFinite(v)) { continue; }
            const x = viewport.indexToX(i) + viewport.barSpacing / 2;
            const y = this._priceToY(v, viewport, null);
            if (!started) { ctx.moveTo(x, y); started = true; }
            else ctx.lineTo(x, y);
        }
        ctx.closePath();
        ctx.fillStyle = fill;
        ctx.fill();
    }

    draw(ctx, viewport, dm, pane, theme) {
        this.ensureCalculated(dm);
        ctx.save();
        this._clipToPane(ctx, viewport, pane);
        this._drawBand(ctx, viewport, this.buffers.upper, this.buffers.lower,
            this._withAlpha(this.color2, 0.05));
        ctx.restore();
        this._drawLine(ctx, viewport, this.buffers.upper,  this.color2, this.lineWidth, pane);
        this._drawLine(ctx, viewport, this.buffers.middle, this.color,  this.lineWidth, pane);
        this._drawLine(ctx, viewport, this.buffers.lower,  this.color2, this.lineWidth, pane);
    }
}


/* === js/indicators/overlays/DonchianChannel.js === */
/**
 * DonchianChannel.js
 * Donchian Channel overlay.
 *   upper[i] = highest high over the previous `period` bars (excluding current)
 *   lower[i] = lowest low over the previous `period` bars (excluding current)
 *   middle[i] = (upper[i] + lower[i]) / 2
 *
 * We use the conventional lookback that includes the current bar; both lines
 * plus a fill between upper and lower are drawn.
 */
class DonchianChannel extends IndicatorBase {
    constructor(opts = {}) {
        super(opts);
        this.name = 'DonchianChannel';
        this.type = 'overlay';
        this.color  = opts.color  || '#12C4F0';
        this.color2 = opts.color2 || '#EA3943';
    }
    defaultOptions() { return { period: 20 }; }
    calculate(dm) {
        const { highs, lows } = dm.raw();
        const n = highs.length;
        const p = this.options.period;
        const upper = this._highest(highs, p);
        const lower = this._lowest(lows, p);
        const middle = new Float64Array(n);
        for (let i = 0; i < n; i++) {
            middle[i] = isFinite(upper[i]) && isFinite(lower[i]) ? (upper[i] + lower[i]) / 2 : NaN;
        }
        this.buffers.upper = upper;
        this.buffers.lower = lower;
        this.buffers.middle = middle;
    }
    _drawBand(ctx, viewport, upper, lower, fill) {
        const leftIdx = Math.max(0, Math.floor(viewport.leftEdge));
        const rightIdx = Math.min(upper.length - 1, Math.ceil(viewport.rightEdge));
        ctx.beginPath();
        let started = false;
        for (let i = leftIdx; i <= rightIdx; i++) {
            const v = upper[i];
            if (!isFinite(v)) { started = false; continue; }
            const x = viewport.indexToX(i) + viewport.barSpacing / 2;
            const y = this._priceToY(v, viewport, null);
            if (!started) { ctx.moveTo(x, y); started = true; }
            else ctx.lineTo(x, y);
        }
        started = false;
        for (let i = rightIdx; i >= leftIdx; i--) {
            const v = lower[i];
            if (!isFinite(v)) { continue; }
            const x = viewport.indexToX(i) + viewport.barSpacing / 2;
            const y = this._priceToY(v, viewport, null);
            if (!started) { ctx.moveTo(x, y); started = true; }
            else ctx.lineTo(x, y);
        }
        ctx.closePath();
        ctx.fillStyle = fill;
        ctx.fill();
    }
    draw(ctx, viewport, dm, pane, theme) {
        this.ensureCalculated(dm);
        ctx.save();
        this._clipToPane(ctx, viewport, pane);
        this._drawBand(ctx, viewport, this.buffers.upper, this.buffers.lower,
            this._withAlpha(this.color2, 0.05));
        ctx.restore();
        this._drawLine(ctx, viewport, this.buffers.upper,  this.color2, this.lineWidth, pane);
        this._drawLine(ctx, viewport, this.buffers.middle, this.color,  this.lineWidth, pane);
        this._drawLine(ctx, viewport, this.buffers.lower,  this.color2, this.lineWidth, pane);
    }
}


/* === js/indicators/overlays/SuperTrend.js === */
/**
 * SuperTrend.js
 * ATR-based trend overlay.
 *
 *   ATR     = RMA(TR, atrPeriod),  TR = max(high-low, |high-prevClose|, |low-prevClose|)
 *   HL2     = (high + low) / 2
 *   bUp     = HL2 + mult * ATR
 *   bDn     = HL2 - mult * ATR
 *   fUp[i]  = (bUp[i] < fUp[i-1] || close[i-1] > fUp[i-1]) ? bUp[i] : fUp[i-1]
 *   fDn[i]  = (bDn[i] > fDn[i-1] || close[i-1] < fDn[i-1]) ? bDn[i] : fDn[i-1]
 *   trend[i]:
 *     if trend[i-1] == -1 and close[i] > fUp[i-1]: trend = 1
 *     else if trend[i-1] == 1 and close[i] < fDn[i-1]: trend = -1
 *     else: trend = trend[i-1]
 *   superTrend[i] = trend[i] == 1 ? fDn[i] : fUp[i]
 *
 * Color: green (color3) when uptrend, red (color2) when downtrend.
 */
class SuperTrend extends IndicatorBase {
    constructor(opts = {}) {
        super(opts);
        this.name = 'SuperTrend';
        this.type = 'overlay';
        this.color2 = opts.color2 || '#EA3943'; // downtrend (red)
        this.color3 = opts.color3 || '#16C784'; // uptrend (green)
    }
    defaultOptions() { return { period: 10, mult: 3 }; }

    _trueRange(highs, lows, closes) {
        const n = highs.length;
        const tr = new Float64Array(n);
        tr[0] = highs[0] - lows[0];
        for (let i = 1; i < n; i++) {
            const a = highs[i] - lows[i];
            const b = Math.abs(highs[i] - closes[i - 1]);
            const c = Math.abs(lows[i] - closes[i - 1]);
            tr[i] = Math.max(a, b, c);
        }
        return tr;
    }

    calculate(dm) {
        const { highs, lows, closes } = dm.raw();
        const n = closes.length;
        const ap = this.options.period;
        const m = this.options.mult;
        const tr = this._trueRange(highs, lows, closes);
        const atr = this._rma(tr, ap);

        const fUp = new Float64Array(n);
        const fDn = new Float64Array(n);
        const st = new Float64Array(n);
        const trend = new Int8Array(n); // 1 = up, -1 = down

        for (let i = 0; i < n; i++) {
            if (!isFinite(atr[i])) {
                fUp[i] = NaN;
                fDn[i] = NaN;
                st[i] = NaN;
                continue;
            }
            const hl2 = (highs[i] + lows[i]) / 2;
            const bUp = hl2 + m * atr[i];
            const bDn = hl2 - m * atr[i];

            if (i === 0 || !isFinite(fUp[i - 1])) {
                fUp[i] = bUp;
                fDn[i] = bDn;
                trend[i] = closes[i] >= hl2 ? 1 : -1;
                st[i] = trend[i] === 1 ? fDn[i] : fUp[i];
                continue;
            }

            fUp[i] = (bUp < fUp[i - 1] || closes[i - 1] > fUp[i - 1]) ? bUp : fUp[i - 1];
            fDn[i] = (bDn > fDn[i - 1] || closes[i - 1] < fDn[i - 1]) ? bDn : fDn[i - 1];

            const prevTrend = trend[i - 1];
            if (prevTrend === -1 && closes[i] > fUp[i - 1]) {
                trend[i] = 1;
            } else if (prevTrend === 1 && closes[i] < fDn[i - 1]) {
                trend[i] = -1;
            } else {
                trend[i] = prevTrend;
            }
            st[i] = trend[i] === 1 ? fDn[i] : fUp[i];
        }
        this.buffers.supertrend = st;
        this.buffers.trend = trend;
    }

    draw(ctx, viewport, dm, pane, theme) {
        this.ensureCalculated(dm);
        const buf = this.buffers.supertrend;
        const trend = this.buffers.trend;
        if (!buf) return;
        const leftIdx = Math.max(0, Math.floor(viewport.leftEdge));
        const rightIdx = Math.min(buf.length - 1, Math.ceil(viewport.rightEdge));
        ctx.lineWidth = this.lineWidth;
        ctx.setLineDash([]);

        // Draw two passes: one for uptrend segments (green) and one for downtrend (red).
        for (let pass = 0; pass < 2; pass++) {
            const wantTrend = pass === 0 ? 1 : -1;
            const color = wantTrend === 1 ? this.color3 : this.color2;
            ctx.strokeStyle = color;
            ctx.beginPath();
            let started = false;
            for (let i = leftIdx; i <= rightIdx; i++) {
                if (!isFinite(buf[i]) || trend[i] !== wantTrend) { started = false; continue; }
                const x = viewport.indexToX(i) + viewport.barSpacing / 2;
                const y = this._priceToY(buf[i], viewport, pane);
                if (!started) { ctx.moveTo(x, y); started = true; }
                else ctx.lineTo(x, y);
                // Bridge to next bar if it's same trend (handle single-bar gaps gracefully).
            }
            ctx.stroke();
        }
    }
}


/* === js/indicators/overlays/ParabolicSAR.js === */
/**
 * ParabolicSAR.js
 * Parabolic Stop-and-Reverse overlay.
 *
 * Standard Welles Wilder algorithm:
 *   - Acceleration factor (af) starts at 0.02, increments by 0.02 on each new
 *     extreme, capped at 0.2.
 *   - In an uptrend:
 *       SAR[i] = SAR[i-1] + af * (EP - SAR[i-1])
 *       SAR[i] = min(SAR[i], low[i-1], low[i-2])    // clamp
 *       if low[i] < SAR[i]: reverse to downtrend
 *           SAR[i] = EP ; EP = low[i] ; af = 0.02
 *       else if high[i] > EP: EP = high[i] ; af = min(af + 0.02, 0.2)
 *   - In a downtrend: mirror image (clamp to max of prior two highs, reverse
 *     when high[i] > SAR[i]).
 *
 * Drawn as dots above (downtrend) or below (uptrend) the candles.
 * Up dots green, down dots red.
 */
class ParabolicSAR extends IndicatorBase {
    constructor(opts = {}) {
        super(opts);
        this.name = 'ParabolicSAR';
        this.type = 'overlay';
        this.color2 = opts.color2 || '#EA3943'; // downtrend dot (above)
        this.color3 = opts.color3 || '#16C784'; // uptrend dot (below)
    }
    defaultOptions() { return { start: 0.02, increment: 0.02, max: 0.2 }; }

    calculate(dm) {
        const { highs, lows, closes } = dm.raw();
        const n = closes.length;
        if (n === 0) {
            this.buffers.psar = new Float64Array(0);
            this.buffers.trend = new Int8Array(0);
            return;
        }
        const psar = new Float64Array(n);
        const trend = new Int8Array(n); // 1 = up, -1 = down
        const start = this.options.start;
        const inc = this.options.increment;
        const maxAF = this.options.max;

        // Initialise: assume uptrend from bar 0, EP = high[0], SAR = low[0].
        let af = start;
        let ep = highs[0];
        let sar = lows[0];
        let tr = 1; // up

        for (let i = 0; i < n; i++) {
            if (i === 0) {
                psar[i] = sar;
                trend[i] = tr;
                // Update EP for bar 0 itself.
                if (highs[i] > ep) ep = highs[i];
                continue;
            }
            // Carry forward: compute tentative SAR for this bar.
            let newSAR = sar + af * (ep - sar);
            // Clamp SAR to prior two lows (uptrend) / highs (downtrend).
            if (tr === 1) {
                newSAR = Math.min(newSAR, lows[i - 1],
                    i >= 2 ? lows[i - 2] : lows[i - 1]);
            } else {
                newSAR = Math.max(newSAR, highs[i - 1],
                    i >= 2 ? highs[i - 2] : highs[i - 1]);
            }
            // Check for reversal.
            if (tr === 1 && lows[i] < newSAR) {
                // Reverse to downtrend.
                tr = -1;
                sar = ep; // SAR becomes the prior EP (highest high)
                ep = lows[i];
                af = start;
                psar[i] = sar;
                trend[i] = tr;
                continue;
            }
            if (tr === -1 && highs[i] > newSAR) {
                // Reverse to uptrend.
                tr = 1;
                sar = ep; // SAR becomes prior EP (lowest low)
                ep = highs[i];
                af = start;
                psar[i] = sar;
                trend[i] = tr;
                continue;
            }
            // No reversal: accept tentative SAR, update EP/AF.
            sar = newSAR;
            if (tr === 1) {
                if (highs[i] > ep) { ep = highs[i]; af = Math.min(af + inc, maxAF); }
            } else {
                if (lows[i] < ep) { ep = lows[i]; af = Math.min(af + inc, maxAF); }
            }
            psar[i] = sar;
            trend[i] = tr;
        }
        this.buffers.psar = psar;
        this.buffers.trend = trend;
    }

    draw(ctx, viewport, dm, pane, theme) {
        this.ensureCalculated(dm);
        const psar = this.buffers.psar;
        const trend = this.buffers.trend;
        if (!psar || psar.length === 0) return;
        const leftIdx = Math.max(0, Math.floor(viewport.leftEdge));
        const rightIdx = Math.min(psar.length - 1, Math.ceil(viewport.rightEdge));
        const r = Math.max(1.2, viewport.barSpacing * 0.18);
        ctx.save();
        this._clipToPane(ctx, viewport, pane);
        for (let i = leftIdx; i <= rightIdx; i++) {
            const v = psar[i];
            if (!isFinite(v)) continue;
            const x = viewport.indexToX(i) + viewport.barSpacing / 2;
            const y = this._priceToY(v, viewport, pane);
            ctx.fillStyle = trend[i] === 1 ? this.color3 : this.color2;
            ctx.beginPath();
            ctx.arc(x, y, r, 0, Math.PI * 2);
            ctx.fill();
        }
        ctx.restore();
    }
}


/* === js/indicators/overlays/IchimokuCloud.js === */
/**
 * IchimokuCloud.js
 * Ichimoku Kinko Hyo overlay.
 *
 *   Tenkan-sen  = (highest(high, 9)  + lowest(low, 9))  / 2
 *   Kijun-sen   = (highest(high, 26) + lowest(low, 26)) / 2
 *   Senkou A    = (Tenkan + Kijun) / 2, plotted 26 bars ahead
 *   Senkou B    = (highest(high, 52) + lowest(low, 52)) / 2, plotted 26 bars ahead
 *   Chikou Span = close, plotted 26 bars back
 *
 * The "cloud" (Kumo) is the region between Senkou A and Senkou B. We render
 * the cloud as a filled polygon (green where A >= B, red where A < B), plus
 * the five lines. Senkou A/B are drawn at index `i + displacement`; Chikou
 * at `i - displacement`.
 */
class IchimokuCloud extends IndicatorBase {
    constructor(opts = {}) {
        super(opts);
        this.name = 'IchimokuCloud';
        this.type = 'overlay';
        this.color  = opts.color  || '#12C4F0'; // Tenkan
        this.color2 = opts.color2 || '#EA3943'; // Kijun
        this.color3 = opts.color3 || '#16C784'; // Senkou A
    }
    defaultOptions() { return { tenkan: 9, kijun: 26, senkouB: 52, displacement: 26 }; }

    calculate(dm) {
        const { highs, lows, closes } = dm.raw();
        const n = closes.length;
        const tP = this.options.tenkan;
        const kP = this.options.kijun;
        const sbP = this.options.senkouB;
        const d = this.options.displacement;

        const tenkanH = this._highest(highs, tP);
        const tenkanL = this._lowest(lows, tP);
        const kijunH  = this._highest(highs, kP);
        const kijunL  = this._lowest(lows, kP);
        const senkouBH = this._highest(highs, sbP);
        const senkouBL = this._lowest(lows, sbP);

        const tenkan = new Float64Array(n);
        const kijun  = new Float64Array(n);
        const senkouA = new Float64Array(n);
        const senkouB = new Float64Array(n);
        for (let i = 0; i < n; i++) {
            tenkan[i]  = (isFinite(tenkanH[i]) && isFinite(tenkanL[i]))  ? (tenkanH[i] + tenkanL[i]) / 2  : NaN;
            kijun[i]   = (isFinite(kijunH[i])  && isFinite(kijunL[i]))   ? (kijunH[i]  + kijunL[i])  / 2  : NaN;
            senkouA[i] = (isFinite(tenkan[i]) && isFinite(kijun[i]))    ? (tenkan[i] + kijun[i]) / 2     : NaN;
            senkouB[i] = (isFinite(senkouBH[i]) && isFinite(senkouBL[i])) ? (senkouBH[i] + senkouBL[i]) / 2 : NaN;
        }
        this.buffers.tenkan = tenkan;
        this.buffers.kijun = kijun;
        this.buffers.senkouA = senkouA;
        this.buffers.senkouB = senkouB;
        this.buffers.chikou = closes;
        this._displacement = d;
    }

    /** Plot a buffer shifted by `shift` bars (positive = right/ahead). */
    _drawShifted(ctx, viewport, buf, shift, color, lineWidth, pane, dash) {
        const n = buf.length;
        const leftIdx = Math.max(0, Math.floor(viewport.leftEdge - shift));
        const rightIdx = Math.min(n - 1, Math.ceil(viewport.rightEdge - shift));
        ctx.strokeStyle = color;
        ctx.lineWidth = lineWidth;
        if (dash) ctx.setLineDash(dash); else ctx.setLineDash([]);
        ctx.beginPath();
        let started = false;
        for (let i = leftIdx; i <= rightIdx; i++) {
            const v = buf[i];
            if (!isFinite(v)) { started = false; continue; }
            const plotIdx = i + shift;
            const x = viewport.indexToX(plotIdx) + viewport.barSpacing / 2;
            const y = this._priceToY(v, viewport, pane);
            if (!started) { ctx.moveTo(x, y); started = true; }
            else ctx.lineTo(x, y);
        }
        ctx.stroke();
        ctx.setLineDash([]);
    }

    _drawCloud(ctx, viewport, a, b, shift, pane) {
        const n = a.length;
        const leftIdx = Math.max(0, Math.floor(viewport.leftEdge - shift));
        const rightIdx = Math.min(n - 1, Math.ceil(viewport.rightEdge - shift));
        // Build a polygon by walking A forward then B back, splitting into
        // contiguous non-NaN runs.
        let i = leftIdx;
        while (i <= rightIdx) {
            // Skip leading NaNs.
            while (i <= rightIdx && !(isFinite(a[i]) && isFinite(b[i]))) i++;
            if (i > rightIdx) break;
            const runStart = i;
            while (i <= rightIdx && isFinite(a[i]) && isFinite(b[i])) i++;
            const runEnd = i - 1;
            // Build polygon for [runStart..runEnd].
            ctx.beginPath();
            for (let k = runStart; k <= runEnd; k++) {
                const x = viewport.indexToX(k + shift) + viewport.barSpacing / 2;
                const y = this._priceToY(a[k], viewport, pane);
                if (k === runStart) ctx.moveTo(x, y); else ctx.lineTo(x, y);
            }
            for (let k = runEnd; k >= runStart; k--) {
                const x = viewport.indexToX(k + shift) + viewport.barSpacing / 2;
                const y = this._priceToY(b[k], viewport, pane);
                ctx.lineTo(x, y);
            }
            ctx.closePath();
            // Cloud colour: green when A >= B (bullish), red when A < B (bearish).
            // Use the relationship at the midpoint of the run as a simple heuristic.
            const mid = (runStart + runEnd) >> 1;
            const bullish = a[mid] >= b[mid];
            ctx.fillStyle = bullish
                ? this._withAlpha(this.color3, 0.15)
                : this._withAlpha(this.color2, 0.15);
            ctx.fill();
        }
    }

    draw(ctx, viewport, dm, pane, theme) {
        this.ensureCalculated(dm);
        const d = this._displacement;
        // Cloud fill (behind lines).
        ctx.save();
        this._clipToPane(ctx, viewport, pane);
        this._drawCloud(ctx, viewport, this.buffers.senkouA, this.buffers.senkouB, d, pane);
        ctx.restore();
        // Senkou A & B (shifted forward by `d`).
        this._drawShifted(ctx, viewport, this.buffers.senkouA, d, this.color3, this.lineWidth, pane);
        this._drawShifted(ctx, viewport, this.buffers.senkouB, d, this.color2, this.lineWidth, pane);
        // Tenkan / Kijun (no shift).
        this._drawLine(ctx, viewport, this.buffers.tenkan, this.color,  this.lineWidth, pane);
        this._drawLine(ctx, viewport, this.buffers.kijun,  this.color2, this.lineWidth, pane);
        // Chikou (close shifted back by `d`).
        this._drawShifted(ctx, viewport, this.buffers.chikou, -d, '#787b86', this.lineWidth, pane, [2, 3]);
    }
}


/* === js/indicators/overlays/ZigZag.js === */
/**
 * ZigZag.js
 * Pivot-based ZigZag overlay.
 *
 * Walks the bars and identifies significant swing highs / lows where price
 * retraced by at least `percent` % from the prior pivot. Draws straight line
 * segments connecting consecutive pivots and marks each pivot with a dot.
 *
 * Implementation:
 *   - Scan forward to find the first swing whose total range exceeds the
 *     threshold; that establishes the first two pivots (low then high, or
 *     high then low) and the initial search direction.
 *   - From the last pivot, track the running extreme in the current search
 *     direction. When the opposite extreme retraces by `percent` from the
 *     running extreme, lock in a new pivot and reverse direction.
 *   - The in-progress (unconfirmed) running extreme is appended as a final
 *     pivot so the line extends to the latest bar.
 */
class ZigZag extends IndicatorBase {
    constructor(opts = {}) {
        super(opts);
        this.name = 'ZigZag';
        this.type = 'overlay';
        this.color  = opts.color  || '#12C4F0'; // line
        this.color2 = opts.color2 || '#EA3943'; // pivot dots
    }
    defaultOptions() { return { percent: 5 }; }

    calculate(dm) {
        const { highs, lows } = dm.raw();
        const n = highs.length;
        const out = new Float64Array(n).fill(NaN); // NaN except at pivot indices
        const pivots = [];
        const thr = this.options.percent / 100;
        if (n === 0) { this.buffers.zigzag = out; this.buffers.pivots = pivots; return; }

        // 1) Find the initial pair of pivots.
        let h = highs[0], hIdx = 0, l = lows[0], lIdx = 0;
        let found = false;
        for (let i = 1; i < n; i++) {
            if (highs[i] > h) { h = highs[i]; hIdx = i; }
            if (lows[i]  < l) { l = lows[i];  lIdx = i; }
            if (h > 0 && (h - l) / h >= thr) {
                if (lIdx < hIdx) {
                    pivots.push({ index: lIdx, price: l, type: 'low'  });
                    pivots.push({ index: hIdx, price: h, type: 'high' });
                } else {
                    pivots.push({ index: hIdx, price: h, type: 'high' });
                    pivots.push({ index: lIdx, price: l, type: 'low'  });
                }
                found = true;
                break;
            }
        }
        if (!found) { this.buffers.zigzag = out; this.buffers.pivots = pivots; return; }

        // 2) Continue from the last pivot.
        let last = pivots[pivots.length - 1];
        let dir = last.type === 'low' ? 1 : -1; // 1 = searching for high, -1 = searching for low
        let curExt = last.price;
        let curExtIdx = last.index;

        for (let i = last.index + 1; i < n; i++) {
            if (dir === 1) {
                if (highs[i] > curExt) { curExt = highs[i]; curExtIdx = i; }
                const retrace = curExt > 0 ? (curExt - lows[i]) / curExt : 0;
                if (retrace >= thr) {
                    pivots.push({ index: curExtIdx, price: curExt, type: 'high' });
                    curExt = lows[i]; curExtIdx = i;
                    dir = -1;
                }
            } else {
                if (lows[i] < curExt) { curExt = lows[i]; curExtIdx = i; }
                const retrace = curExt > 0 ? (highs[i] - curExt) / curExt : 0;
                if (retrace >= thr) {
                    pivots.push({ index: curExtIdx, price: curExt, type: 'low' });
                    curExt = highs[i]; curExtIdx = i;
                    dir = 1;
                }
            }
        }
        // Append the in-progress extreme so the line extends to the latest bar.
        if (curExtIdx !== last.index) {
            pivots.push({ index: curExtIdx, price: curExt, type: dir === 1 ? 'high' : 'low' });
        }

        for (const p of pivots) {
            if (p.index >= 0 && p.index < n) out[p.index] = p.price;
        }
        this.buffers.zigzag = out;
        this.buffers.pivots = pivots;
    }

    draw(ctx, viewport, dm, pane, theme) {
        this.ensureCalculated(dm);
        const pivots = this.buffers.pivots;
        if (!pivots || pivots.length < 2) return;
        const leftIdx = Math.max(0, Math.floor(viewport.leftEdge));
        const rightIdx = Math.ceil(viewport.rightEdge);
        ctx.strokeStyle = this.color;
        ctx.lineWidth = this.lineWidth;
        ctx.setLineDash([]);
        ctx.beginPath();
        let started = false;
        for (const p of pivots) {
            if (p.index < leftIdx - 1 || p.index > rightIdx + 1) continue;
            const x = viewport.indexToX(p.index) + viewport.barSpacing / 2;
            const y = this._priceToY(p.price, viewport, pane);
            if (!started) { ctx.moveTo(x, y); started = true; }
            else ctx.lineTo(x, y);
        }
        ctx.stroke();

        // Pivot dots.
        ctx.fillStyle = this.color2;
        const r = Math.max(2, viewport.barSpacing * 0.15);
        for (const p of pivots) {
            if (p.index < leftIdx - 1 || p.index > rightIdx + 1) continue;
            const x = viewport.indexToX(p.index) + viewport.barSpacing / 2;
            const y = this._priceToY(p.price, viewport, pane);
            ctx.beginPath();
            ctx.arc(x, y, r, 0, Math.PI * 2);
            ctx.fill();
        }
    }
}


/* === js/indicators/overlays/PivotPoints.js === */
/**
 * PivotPoints.js
 * Classic (daily) Pivot Points overlay.
 *
 * For each trading day, the prior day's high/low/close are used to compute:
 *   PP = (H + L + C) / 3
 *   R1 = 2*PP - L        S1 = 2*PP - H
 *   R2 = PP + (H - L)    S2 = PP - (H - L)
 *   R3 = H + 2*(PP - L)  S3 = L - 2*(H - PP)
 *
 * These levels are drawn as horizontal lines spanning the current day's bars.
 */
class PivotPoints extends IndicatorBase {
    constructor(opts = {}) {
        super(opts);
        this.name = 'PivotPoints';
        this.type = 'overlay';
        this.color  = opts.color  || '#12C4F0'; // PP
        this.color2 = opts.color2 || '#EA3943'; // Resistance
        this.color3 = opts.color3 || '#16C784'; // Support
    }
    defaultOptions() { return {}; }

    static _dayOf(ts) {
        const DAY = 86_400_000;
        return Math.floor(ts / DAY) * DAY;
    }

    calculate(dm) {
        const { highs, lows, closes, times } = dm.raw();
        const n = closes.length;
        if (n === 0) {
            this.buffers.pp = new Float64Array(0);
            this.buffers.levels = [];
            return;
        }

        // Walk day by day; for each new day compute the levels from the prior day.
        const pp  = new Float64Array(n);
        const r1  = new Float64Array(n);
        const r2  = new Float64Array(n);
        const r3  = new Float64Array(n);
        const s1  = new Float64Array(n);
        const s2  = new Float64Array(n);
        const s3  = new Float64Array(n);
        for (let i = 0; i < n; i++) {
            pp[i] = r1[i] = r2[i] = r3[i] = s1[i] = s2[i] = s3[i] = NaN;
        }

        let curDay = PivotPoints._dayOf(times[0]);
        let dayStart = 0;
        let dayH = highs[0], dayL = lows[0], dayC = closes[0];
        const levels = []; // {dayStart, dayEnd, pp, r1, r2, r3, s1, s2, s3}

        for (let i = 1; i < n; i++) {
            const d = PivotPoints._dayOf(times[i]);
            if (d === curDay) {
                if (highs[i] > dayH) dayH = highs[i];
                if (lows[i]  < dayL) dayL = lows[i];
                dayC = closes[i];
            } else {
                // Day boundary: emit (no levels apply to the first day yet).
                levels.push({ dayStart, dayEnd: i - 1, computed: false });
                curDay = d;
                dayStart = i;
                dayH = highs[i]; dayL = lows[i]; dayC = closes[i];
            }
        }
        levels.push({ dayStart, dayEnd: n - 1, computed: false });

        // For each day >= 1, compute levels from prior day and assign to that day's bars.
        for (let d = 1; d < levels.length; d++) {
            const prev = levels[d - 1];
            // Compute prior-day H/L/C by scanning its bars (we didn't store them).
            let pH = -Infinity, pL = Infinity, pC = NaN;
            for (let i = prev.dayStart; i <= prev.dayEnd; i++) {
                if (highs[i] > pH) pH = highs[i];
                if (lows[i]  < pL) pL = lows[i];
                pC = closes[i];
            }
            const P  = (pH + pL + pC) / 3;
            const R1 = 2 * P - pL;
            const S1 = 2 * P - pH;
            const R2 = P + (pH - pL);
            const S2 = P - (pH - pL);
            const R3 = pH + 2 * (P - pL);
            const S3 = pL - 2 * (pH - P);
            const cur = levels[d];
            cur.computed = true;
            cur.pp = P; cur.r1 = R1; cur.r2 = R2; cur.r3 = R3;
            cur.s1 = S1; cur.s2 = S2; cur.s3 = S3;
            for (let i = cur.dayStart; i <= cur.dayEnd; i++) {
                pp[i] = P; r1[i] = R1; r2[i] = R2; r3[i] = R3;
                s1[i] = S1; s2[i] = S2; s3[i] = S3;
            }
        }

        this.buffers.pp = pp;
        this.buffers.r1 = r1; this.buffers.r2 = r2; this.buffers.r3 = r3;
        this.buffers.s1 = s1; this.buffers.s2 = s2; this.buffers.s3 = s3;
        this.buffers.levels = levels;
    }

    _drawLevel(ctx, viewport, buf, color, pane, dash) {
        const leftIdx = Math.max(0, Math.floor(viewport.leftEdge));
        const rightIdx = Math.min(buf.length - 1, Math.ceil(viewport.rightEdge));
        ctx.strokeStyle = color;
        ctx.lineWidth = 1;
        if (dash) ctx.setLineDash(dash); else ctx.setLineDash([]);
        // Draw contiguous runs of equal value (within a day) as horizontal lines.
        ctx.beginPath();
        let started = false;
        for (let i = leftIdx; i <= rightIdx; i++) {
            const v = buf[i];
            if (!isFinite(v)) { started = false; continue; }
            const x1 = viewport.indexToX(i);
            const x2 = x1 + viewport.barSpacing;
            const y = this._priceToY(v, viewport, pane);
            ctx.moveTo(x1, y);
            ctx.lineTo(x2, y);
        }
        ctx.stroke();
        ctx.setLineDash([]);
    }

    draw(ctx, viewport, dm, pane, theme) {
        this.ensureCalculated(dm);
        this._drawLevel(ctx, viewport, this.buffers.r3, this.color2, pane);
        this._drawLevel(ctx, viewport, this.buffers.r2, this.color2, pane);
        this._drawLevel(ctx, viewport, this.buffers.r1, this.color2, pane);
        this._drawLevel(ctx, viewport, this.buffers.pp, this.color,  pane, [4, 4]);
        this._drawLevel(ctx, viewport, this.buffers.s1, this.color3, pane);
        this._drawLevel(ctx, viewport, this.buffers.s2, this.color3, pane);
        this._drawLevel(ctx, viewport, this.buffers.s3, this.color3, pane);
    }
}


/* === js/indicators/overlays/LinearRegression.js === */
/**
 * LinearRegression.js
 * Linear Regression channel overlay.
 *
 * For each bar i, fits an ordinary least-squares line over the previous
 * `period` closes (inclusive) and outputs:
 *   - the regression value at bar i (middle)
 *   - the residual standard deviation over the window
 *   - upper = middle + mult * stdev
 *   - lower = middle - mult * stdev
 *
 * Renders the middle regression line plus ±mult stdev channel lines and a
 * translucent fill between upper and lower.
 */
class LinearRegression extends IndicatorBase {
    constructor(opts = {}) {
        super(opts);
        this.name = 'LinearRegression';
        this.type = 'overlay';
        this.color  = opts.color  || '#12C4F0';
        this.color2 = opts.color2 || '#EA3943';
    }
    defaultOptions() { return { period: 20, mult: 2 }; }
    calculate(dm) {
        const { closes } = dm.raw();
        const n = closes.length;
        const p = this.options.period;
        const m = this.options.mult;
        const middle = new Float64Array(n).fill(NaN);
        const upper = new Float64Array(n).fill(NaN);
        const lower = new Float64Array(n).fill(NaN);
        // Precompute sums of x and x*x for x = 0..p-1 (independent variable).
        const xs = p * (p - 1) / 2;
        const xx = (p - 1) * p * (2 * p - 1) / 6;
        const xMean = (p - 1) / 2;
        const denomX = xx - p * xMean * xMean;
        for (let i = p - 1; i < n; i++) {
            let sy = 0, sxy = 0;
            for (let j = 0; j < p; j++) {
                const y = closes[i - p + 1 + j];
                sy += y;
                sxy += j * y;
            }
            const yMean = sy / p;
            const slope = denomX !== 0 ? (sxy - p * xMean * yMean) / denomX : 0;
            const intercept = yMean - slope * xMean;
            // Regression value at the rightmost x = p - 1.
            const reg = intercept + slope * (p - 1);
            // Residual stdev.
            let ssr = 0;
            for (let j = 0; j < p; j++) {
                const yhat = intercept + slope * j;
                const y = closes[i - p + 1 + j];
                ssr += (y - yhat) ** 2;
            }
            const sd = Math.sqrt(ssr / p);
            middle[i] = reg;
            upper[i] = reg + m * sd;
            lower[i] = reg - m * sd;
        }
        this.buffers.middle = middle;
        this.buffers.upper = upper;
        this.buffers.lower = lower;
    }
    _drawBand(ctx, viewport, upper, lower, fill) {
        const leftIdx = Math.max(0, Math.floor(viewport.leftEdge));
        const rightIdx = Math.min(upper.length - 1, Math.ceil(viewport.rightEdge));
        ctx.beginPath();
        let started = false;
        for (let i = leftIdx; i <= rightIdx; i++) {
            const v = upper[i];
            if (!isFinite(v)) { started = false; continue; }
            const x = viewport.indexToX(i) + viewport.barSpacing / 2;
            const y = this._priceToY(v, viewport, null);
            if (!started) { ctx.moveTo(x, y); started = true; }
            else ctx.lineTo(x, y);
        }
        started = false;
        for (let i = rightIdx; i >= leftIdx; i--) {
            const v = lower[i];
            if (!isFinite(v)) { continue; }
            const x = viewport.indexToX(i) + viewport.barSpacing / 2;
            const y = this._priceToY(v, viewport, null);
            if (!started) { ctx.moveTo(x, y); started = true; }
            else ctx.lineTo(x, y);
        }
        ctx.closePath();
        ctx.fillStyle = fill;
        ctx.fill();
    }
    draw(ctx, viewport, dm, pane, theme) {
        this.ensureCalculated(dm);
        ctx.save();
        this._clipToPane(ctx, viewport, pane);
        this._drawBand(ctx, viewport, this.buffers.upper, this.buffers.lower,
            this._withAlpha(this.color2, 0.05));
        ctx.restore();
        this._drawLine(ctx, viewport, this.buffers.upper,  this.color2, this.lineWidth, pane);
        this._drawLine(ctx, viewport, this.buffers.middle, this.color,  this.lineWidth, pane);
        this._drawLine(ctx, viewport, this.buffers.lower,  this.color2, this.lineWidth, pane);
    }
}


/* === js/indicators/overlays/MAribbon.js === */
/**
 * MAribbon.js
 * Moving Average ribbon overlay — 4 SMAs with periods 10/20/50/100.
 *
 * Each MA is drawn in a distinct colour so crossovers/stacking are visible.
 */
class MAribbon extends IndicatorBase {
    constructor(opts = {}) {
        super(opts);
        this.name = 'MAribbon';
        this.type = 'overlay';
        this.color  = opts.color  || '#12C4F0'; // 10
        this.color2 = opts.color2 || '#EA3943'; // 20
        this.color3 = opts.color3 || '#16C784'; // 50
        this.color4 = opts.color4 || '#ff9800'; // 100
    }
    defaultOptions() { return { periods: [10, 20, 50, 100] }; }
    calculate(dm) {
        const { closes } = dm.raw();
        const periods = this.options.periods;
        this.buffers.mas = periods.map(p => this._sma(closes, p));
    }
    draw(ctx, viewport, dm, pane, theme) {
        this.ensureCalculated(dm);
        const colors = [this.color, this.color2, this.color3, this.color4];
        this.buffers.mas.forEach((buf, i) => {
            const c = colors[i % colors.length];
            this._drawLine(ctx, viewport, buf, c, this.lineWidth, pane);
        });
    }
}


/* === js/indicators/overlays/EnvChannel.js === */
/**
 * EnvChannel.js
 * Envelope channel overlay.
 *   middle = SMA(close, period)
 *   upper  = middle * (1 + pct)
 *   lower  = middle * (1 - pct)
 * Renders 3 lines plus a translucent fill between upper and lower.
 */
class EnvChannel extends IndicatorBase {
    constructor(opts = {}) {
        super(opts);
        this.name = 'EnvChannel';
        this.type = 'overlay';
        this.color  = opts.color  || '#12C4F0';
        this.color2 = opts.color2 || '#EA3943';
    }
    defaultOptions() { return { period: 20, percent: 0.025 }; }
    calculate(dm) {
        const { closes } = dm.raw();
        const n = closes.length;
        const p = this.options.period;
        const pct = this.options.percent;
        const middle = this._sma(closes, p);
        const upper = new Float64Array(n);
        const lower = new Float64Array(n);
        for (let i = 0; i < n; i++) {
            if (isFinite(middle[i])) {
                upper[i] = middle[i] * (1 + pct);
                lower[i] = middle[i] * (1 - pct);
            } else {
                upper[i] = NaN;
                lower[i] = NaN;
            }
        }
        this.buffers.middle = middle;
        this.buffers.upper = upper;
        this.buffers.lower = lower;
    }
    _drawBand(ctx, viewport, upper, lower, fill) {
        const leftIdx = Math.max(0, Math.floor(viewport.leftEdge));
        const rightIdx = Math.min(upper.length - 1, Math.ceil(viewport.rightEdge));
        ctx.beginPath();
        let started = false;
        for (let i = leftIdx; i <= rightIdx; i++) {
            const v = upper[i];
            if (!isFinite(v)) { started = false; continue; }
            const x = viewport.indexToX(i) + viewport.barSpacing / 2;
            const y = this._priceToY(v, viewport, null);
            if (!started) { ctx.moveTo(x, y); started = true; }
            else ctx.lineTo(x, y);
        }
        started = false;
        for (let i = rightIdx; i >= leftIdx; i--) {
            const v = lower[i];
            if (!isFinite(v)) { continue; }
            const x = viewport.indexToX(i) + viewport.barSpacing / 2;
            const y = this._priceToY(v, viewport, null);
            if (!started) { ctx.moveTo(x, y); started = true; }
            else ctx.lineTo(x, y);
        }
        ctx.closePath();
        ctx.fillStyle = fill;
        ctx.fill();
    }
    draw(ctx, viewport, dm, pane, theme) {
        this.ensureCalculated(dm);
        ctx.save();
        this._clipToPane(ctx, viewport, pane);
        this._drawBand(ctx, viewport, this.buffers.upper, this.buffers.lower,
            this._withAlpha(this.color2, 0.05));
        ctx.restore();
        this._drawLine(ctx, viewport, this.buffers.upper,  this.color2, this.lineWidth, pane);
        this._drawLine(ctx, viewport, this.buffers.middle, this.color,  this.lineWidth, pane, [4, 4]);
        this._drawLine(ctx, viewport, this.buffers.lower,  this.color2, this.lineWidth, pane);
    }
}


